import { v7 as uuidv7 } from 'uuid';
import * as z from 'zod';

/**
 * RFC 9562 UUID string (any version). Every platform id is a UUID; new ids are
 * v7 (time ordered) and generated by the application, see {@link newId}.
 */
export const UuidSchema = z.uuid().describe('UUID');

/** Zod schema of a UUID that must be version 7. */
export const UuidV7Schema = z.uuid({ version: 'v7' }).describe('UUID v7');

/**
 * Generates a new time-ordered UUID v7 (monotonic within the same millisecond).
 * Works in Node.js and in browsers.
 *
 * @example const vesselId = newId(); // "019a9f4e-8c1d-7b52-9f3e-6a2d4c1b0e7f"
 */
export function newId(): string {
  return uuidv7();
}

/** Returns `true` when `value` is a UUID string of any version. */
export function isUuid(value: unknown): boolean {
  return UuidSchema.safeParse(value).success;
}
